/// <summary>
/// MPJ_34360_TransferOrderReceipt
/// </summary>
public class METInventTransferLine extends common
{

}

Method.Source:
    public METCase calcCases(UnitOfMeasureSymbol    _inventoryUnit)
    {
        METCase                 caseCount;
        UnitOfMeasureSymbol     warehouseUnit;
        InventTransferLine      inventTransferLine;

        inventTransferLine  = this.inventTransferLine();
        warehouseUnit       = this.WarehouseUnitId;

        return caseCount;
    }

    /// <summary>
    /// insert record
    /// </summary>
    public void insert()
    {
        if(this.InventTransferLine)
        {
            InventTransferLine          inventTransferLine;
            InventDim                   inventDim,transferLineInventDim;
            METInventItemOrderSetup     metInventItemOrderSetup;
            METReqItemTable             metReqItemTable;
            ReqItemTable                reqItemTable;


            inventTransferLine          = this.inventTransferLine();
            if(inventTransferLine && (!this.WarehouseCategory || !this.OSCCode || !this.ItemType))
            {
                transferLineInventDim       = inventTransferLine.inventDim();
                metInventItemOrderSetup     = METInventItemOrderSetup::findByItemAndSite(inventTransferLine.ItemId,transferLineInventDim.InventSiteId);
            
                inventDim = null;
                inventDim.InventSiteId      = transferLineInventDim.InventSiteId;
                inventDim.InventLocationId  = transferLineInventDim.InventLocationId;

                inventDim                   = InventDim::findOrCreate(inventDim);
                reqItemTable                = ReqItemTable::find(inventTransferLine.ItemId,inventDim.InventDimId);

                if(!reqItemTable)
                {
                    inventDim = null;
                    inventDim.InventSiteId      = transferLineInventDim.InventSiteId;

                    inventDim                   = InventDim::findOrCreate(inventDim);
                    reqItemTable                = ReqItemTable::find(inventTransferLine.ItemId,inventDim.InventDimId);
                }

                metReqItemTable             = METReqItemTable::find(reqItemTable.RecId);

                this.WarehouseCategory      = metInventItemOrderSetup.FilterCode;
                this.OSCCode                = metReqItemTable.OSCCode;
                this.ItemType               = this.getItemType(inventTransferLine.ItemId, InventLocation::find(inventTransferLine.inventTransferTable().InventLocationIdFrom).InventSiteId);
            }

            this.setCaseQtyFields();
            super();
        }
    }

    /// <summary>
    /// Initialize 
    /// </summary>
    public void initValue()
    {
        InventTransferLine          inventTransferLine;
        InventDim                   inventDim,transferLineInventDim;
        METInventItemOrderSetup     metInventItemOrderSetup;
        METReqItemTable             metReqItemTable;
        ReqItemTable                reqItemTable;

        super();

        inventTransferLine          = this.inventTransferLine();
        if(inventTransferLine)
        {
            transferLineInventDim       = inventTransferLine.inventDim();
            metInventItemOrderSetup     = METInventItemOrderSetup::findByItemAndSite(inventTransferLine.ItemId,transferLineInventDim.InventSiteId);
            
            inventDim = null;
            inventDim.InventSiteId      = transferLineInventDim.InventSiteId;
            inventDim.InventLocationId  = transferLineInventDim.InventLocationId;

            inventDim                   = InventDim::findOrCreate(inventDim);
            reqItemTable                = ReqItemTable::find(inventTransferLine.ItemId,inventDim.InventDimId);

            if(!reqItemTable)
            {
                inventDim = null;
                inventDim.InventSiteId      = transferLineInventDim.InventSiteId;               

                inventDim                   = InventDim::findOrCreate(inventDim);
                reqItemTable                = ReqItemTable::find(inventTransferLine.ItemId,inventDim.InventDimId);
            }

            metReqItemTable             = METReqItemTable::find(reqItemTable.RecId);

            this.WarehouseCategory      = metInventItemOrderSetup.FilterCode;
            this.OSCCode                = metReqItemTable.OSCCode;
			this.ItemType               = this.getItemType(inventTransferLine.ItemId, InventLocation::find(inventTransferLine.inventTransferTable().InventLocationIdFrom).InventSiteId);
        }

        this.setUnitFields(); 
    }

/// <summary>
/// Gets the InventTransferLine record
/// </summary>
/// <returns>
/// InventTransferLine table buffer
/// </returns>
public InventTransferLine inventTransferLine()
{
    return InventTransferLine::findRecId(this.InventTransferLine);
}

    /// <summary>
    /// Set unit weight, unit volume, unit case 
    /// </summary>
    public void setUnitFields()
    {
        InventTransferLine      inventTransferLine = this.InventTransferLine();

        if (inventTransferLine.itemId && inventTransferLine.UnitId && inventTransferLine.InventDimId)
        {
            this.WarehouseUnitId = METInventLocation::getWarehouseUnit(inventTransferLine.itemId, inventTransferLine.inventDimReceive());

            //CS - CB715_TransferOrderExtract - PS

            InventDim inventDimLoc = inventTransferLine.inventDim();

            this.TOUnitWeight = METWHSPhysDimUOMSite::convertWeight(
                                inventTransferLine.itemId, 1, this.WarehouseUnitId, inventDimLoc);
            this.TOUnitVolume = METWHSPhysDimUOMSite::convertVolume(
                                inventTransferLine.itemId, 1,  this.WarehouseUnitId, inventDimLoc);
            this.TOUnitWeightEA = METWHSPhysDimUOMSite::convertWeight(
                                inventTransferLine.itemId, 1, inventTransferLine.UnitId, inventDimLoc);
            this.TOUnitVolumeEA = METWHSPhysDimUOMSite::convertVolume(
                                inventTransferLine.itemId, 1, inventTransferLine.UnitId, inventDimLoc);

            //CE - CB715_TransferOrderExtract - PS
        }
    }

/// <summary>
/// Update unit weight, unit volume, unit case
/// </summary>
public void updateUnitFields()
{
    if (this.RecId)
    {
        ttsbegin;
        this.selectForUpdate(true);
        this.setUnitFields();
        this.setCaseQtyFields();
        this.update();
        ttscommit;
    }
}

    /// <summary>
    /// Set case quantity fields
    /// </summary>
    public void setCaseQtyFields()
    {
        InventTransferLine      inventTransferLine = this.InventTransferLine();
        UnitOfMeasureFromRecId  fromUnit,toUnit;  
        UnitOfMeasureFromRecId  salesDefaultUnit,alternateUnit;
        Factor                  factor, factorCase;
        UnitOfMeasureSymbol     unitInvent          = InventTableModule::find(inventTransferLine.itemId, ModuleInventPurchSales::Invent).UnitId;
        boolean                 isCWItem           = PdsGlobal::pdsIsCWItem(inventTransferLine.ItemId);      
        
        InventDim inventDim = inventTransferLine.inventDim();

        const Weight    roundValue = 0.01; 

        if (!this.WarehouseUnitId)
        {
            this.setUnitFields();
        }

        if (inventTransferLine.itemId && inventTransferLine.UnitId && this.WarehouseUnitId)
        {   
            toUnit              = EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(inventTransferLine.UnitId);
            fromUnit            = EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(this.WarehouseUnitId);

            factor              = EcoResProductUnitConverter::convertForReleasedProduct(
                                    inventTransferLine.ItemId,
                                    inventTransferLine.inventDimId,
                                    1,
                                    fromUnit,
                                    toUnit,
                                    NoYes::No,
                                    NoYes::No);


            InventItemSalesSetup inventItemSalesSetup;
            inventDim               InventDimSetup;

            select firstonly METSalesUnit, METAltSalesUnit, RecId from inventItemSalesSetup
                    where inventItemSalesSetup.ItemId == inventTransferLine.ItemId
                exists join InventDimSetup
                    where InventDimSetup.InventDimId == inventItemSalesSetup.InventDimId
                    &&    InventDimSetup.InventSiteId == inventDim.InventSiteId;

            salesDefaultUnit = EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(inventItemSalesSetup.METSalesUnit);
            alternateUnit = EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(inventItemSalesSetup.METAltSalesUnit ? inventItemSalesSetup.METAltSalesUnit : METConstants::unitEach);
            factorCase = EcoResProductUnitConverter::convertForReleasedProduct(
                                    inventTransferLine.ItemId,
                                    inventTransferLine.inventDimId,
                                    1,
                                    salesDefaultUnit,
                                    alternateUnit,
                                    NoYes::No,
                                    NoYes::No);

            if (isCWItem)
            {
                this.Cases = inventTransferLine.PdsCWQtyTransfer;
                this.BrokenCase = 0;
            }
            else
            {
                this.Cases = inventTransferLine.QtyTransfer div factorCase;
                this.BrokenCase = inventTransferLine.QtyTransfer mod factorCase;
            }


            if (factorCase)
            {
                if (this.TOUnitWeight)
                {
                    this.TotalWeight    = inventTransferLine.QtyTransfer * round(this.TOUnitWeight, roundValue);
                }
                if (this.TOUnitVolume)
                {
                    this.TotalVolume    = inventTransferLine.QtyTransfer * round(this.TOUnitVolume, roundValue);
                }
            }

            // CB715_TransferOrderExtract
            // new field ShipCaseQty to save unit conversion factor and expose it in METWMSTransferOrderTransEntity
            this.ShipCaseQty = factor;
            this.InventoryUnitId = unitInvent;

			if (!this.ItemType)
            {
                this.ItemType = this.getItemType(inventTransferLine.ItemId, InventLocation::find(inventTransferLine.inventTransferTable().InventLocationIdFrom).InventSiteId);
            }

        }
    }

/// <summary>
/// Find sales line record using the invent trans Id and return.
/// </summary>
/// <returns>
/// <t>SalesLine</t> table buffer
/// </returns>
public SalesLine salesLine_InventTransId(boolean _forUpdate = false)
{
    return SalesLine::findInventTransId(this.SalesLineTransId, _forUpdate);
}

/// <summary>
/// Check if a transfer order line exists for a given invent trans id
/// </summary>
/// <param name = "_inventTransId">Sales line inventTransId</param>
/// <returns>true if record exists, otherwise false</returns>
public static boolean existsForSalesLine(InventTransId _inventTransId)
{
    METInventTransferLine transferLine;
    
    select firstonly RecId from transferLine
        where transferLine.SalesLineTransId == _inventTransId;
    
    return transferLine.RecId != 0;
}

    /// <summary>
    /// Gets METInventItemOrderSetup ItemType by item and site Ids.
    /// </summary>
    /// <param name = "_itemId">Item Id.</param>
    /// <param name = "_siteId">Site id.</param>
    /// <returns>ItemType</returns>
    public METItemTypes getItemType(ItemId _itemId = '', InventSiteId _siteId = '')
    {
        METItemTypes itemType;

        if (!_itemId && !_siteId)
        {
            InventTransferLine inventTransferLine = this.InventTransferLine();
            itemType = METInventItemOrderSetup::findByItemAndSite(inventTransferLine.ItemId, InventLocation::find(inventTransferLine.inventTransferTable().InventLocationIdFrom).InventSiteId).ItemType;
        }
        else
        {
            itemType = METInventItemOrderSetup::findByItemAndSite(_itemId, _siteId).ItemType;
        }

        return itemType;
    }

    /// <summary>
    /// Update METInventTransferLine 
    /// </summary>
    public void update()
    {
        this.setCaseQtyFields();

        if (!this.ItemType)
        {
            this.ItemType = this.getItemType();
        }
        this.setUnitFields();
        this.setCaseQtyFields();

        super();
    }

    /// <summary>
    /// Method to update order extract status for a given transfer line. If transfer line buffer is not passed, it will update the status for current buffer.
    /// </summary>
    /// <param name = "_extractionStatus">Extraction status</param>
    /// <param name = "_metInventTransferLine">Met Tranfer line reference</param>
    public void updateExtractionStatus(METOrderExtractStatus _extractionStatus, METInventTransferLine _metInventTransferLine = this)
    {
        
        if (_metInventTransferLine.OrderExtractStatus != _extractionStatus)
        {
            ttsbegin;

            _metInventTransferLine.selectForUpdate(true);
            _metInventTransferLine.OrderExtractStatus = _extractionStatus;
            _metInventTransferLine.update();

            ttscommit;
        }
    }
